theorem literal_substitution_contract {Δ Γ σ p A}
    (hs : TypedSub Δ Γ σ) (hp : Has Γ p A) :
    Has Δ (psub (images σ) p) (P01TC.subst (images σ) A)

theorem j_transport_requires_both_coordinates {Γ A x ρ η y e}
    (h : E (theta Γ A x) ρ (cons .i (cons (eval x η) η)) (cons e (cons y η))) :
    F A ρ η (eval x η) y ∧ Conv e .i

theorem Restricted.raw_embed {n : Nat} {p : Poly} {A : P01DF.Ty}
    {h : Derivation p A} {A' : Ty} (hr : Restricted n h A') :
    Has (rawTel n) p A'

theorem no_allElim {n : Nat} {p : Poly} {B A : P01DF.Ty}
    {h : Derivation p (.all B)} {A' : Ty} :
    ¬ Restricted n (.allElim (A := A) h) A'
